// mddp_fast: Arm pressure p (kPa) and robot vibration vx/vy/vz (g), tag side=L|R
// Returns the line protocol of every sample since this node's previous tick (own ms timestamps).
const lines = global.get('sim').signal('MDDP_184', 'fast', context, flow, Date.now());
if (!lines) return null;
msg.payload = lines;
node.status({ fill: 'green', shape: 'dot', text: lines.split('\n').length + ' points' });
return msg;

